import { Pressable, StyleSheet, Text, View } from "react-native";

export type PlantSummary = {
  id: string; nickname: string; scientificName: string | null;
};
type Props = { plant: PlantSummary; onSelect: (id: string) => void };
export function PlantSummaryCard({ plant, onSelect }: Props) {
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={`Open ${plant.nickname}`}
      onPress={() => onSelect(plant.id)}
      style={({ pressed }) => [styles.card, { opacity: pressed ? 0.8 : 1 }]}
    >
      <View style={styles.mark}><Text accessible={false}>🌿</Text></View>
      <View style={styles.copy}>
        <Text style={styles.name}>{plant.nickname}</Text>
        <Text>{plant.scientificName ?? "Identification uncertain"}</Text>
      </View>
    </Pressable>
  );
}
const styles = StyleSheet.create({
  card: { flexDirection: "row", alignItems: "center", gap: 12,
    padding: 16, borderRadius: 24, minHeight: 88,
    backgroundColor: "#E5FFF1" },
  mark: { width: 48, height: 48, alignItems: "center", justifyContent: "center" },
  copy: { flex: 1, gap: 4 },
  name: { fontSize: 20, fontWeight: "700", color: "#12382B" },
});

import { Alert, FlatList, Text } from "react-native";
import { PlantSummaryCard, type PlantSummary } from "./PlantSummaryCard";

const examples: PlantSummary[] = [
  { id: "lemon_east", nickname: "East balcony lemon", scientificName: null },
  { id: "lemon_west", nickname: "West window lemon", scientificName: null },
];
export default function PlantList() {
  return (
    <FlatList
      data={examples}
      keyExtractor={(plant) => plant.id}
      contentContainerStyle={{ padding: 20, gap: 12 }}
      renderItem={({ item }) => (
        <PlantSummaryCard plant={item}
          onSelect={(id) => Alert.alert("Selected specimen", id)} />
      )}
      ListEmptyComponent={<Text>
        Your first plant will appear here. Use Scan to add a specimen.
      </Text>}
    />
  );
}
